/* eslint-disable no-invalid-this */

'use strict';

// MODULES //

var logger = require( 'debug' );
var isUndefined = require( '@stdlib/assert/is-undefined' );
var isString = require( '@stdlib/assert/is-string' ).isPrimitive;
var isStringArray = require( '@stdlib/assert/is-string-array' ).primitives;
var hasEqualValues = require( '@stdlib/array/base/assert/has-equal-values' );
var copy = require( '@stdlib/array/base/copy' );
var join = require( '@stdlib/array/base/join' );
var format = require( '@stdlib/string/format' );
var defaults = require( './../defaults.js' );
var changeEvent = require( './../change_event.js' );
var prop = require( './properties.js' );


// VARIABLES //

var debug = logger( 'vega:compare:set:'+prop.name );


// MAIN //

/**
* Sets the data fields to sort.
*
* ## Notes
*
* -   When the number of fields changes, the order array is automatically adjusted:
*     -   If fields are added, 'ascending' is appended to the order array.
*     -   If fields are removed, excess order entries are truncated.
*
* @private
* @param {(string|Array<string>)} value - input value
* @throws {TypeError} must be a string or an array of strings
* @returns {void}
*/
function set( value ) {
	var nfields;
	var order;
	var isStr;
	var opts;
	var i;

	isStr = isString( value );
	if ( !isStr && !isStringArray( value ) ) {
		throw new TypeError( format( 'invalid assignment. `%s` must be a string or an array of strings. Value: `%s`.', prop.name, value ) );
	}
	if ( isStr ) {
		value = [ value ];
	} else {
		value = copy( value );
	}
	if ( isUndefined( this[ prop.private ] ) ) {
		debug( 'Current value: %s. New value: ["%s"].', this[ prop.private ], join( value, '", "' ) );
		this[ prop.private ] = value;
		this.emit( 'change', changeEvent( prop.name ) );
		return;
	}
	if ( !hasEqualValues( value, this[ prop.private ] ) ) {
		debug( 'Current value: ["%s"]. New value: ["%s"].', join( this[ prop.private ], '", "' ), join( value, '", "' ) );
		this[ prop.private ] = value;
		this.emit( 'change', changeEvent( prop.name ) );

		// Adjust the order array to match the new number of fields...
		nfields = value.length;
		order = this._order;
		if ( order ) {
			if ( order.length < nfields ) {
				// Pad with default 'ascending' values...
				opts = defaults();
				for ( i = order.length; i < nfields; i++ ) {
					order.push( opts.order[ 0 ] );
				}
			} else if ( order.length > nfields ) {
				// Truncate excess order entries...
				order.length = nfields;
			}
		}
	}
}


// EXPORTS //

module.exports = set;
